<?php
// Included only by native.php after all production tables have TEMPORARY shadows.
config(['mapa_mobile.trips_enabled'=>true]);
$tripFlow=[];
foreach(['created'=>['dispatched'],'dispatched'=>['started'],'started'=>['enroute'],'enroute'=>['completed'],'completed'=>[]] as $code=>$edges)
    $tripFlow[$code]=['code'=>$code,'activities'=>$edges,'complete'=>$code==='completed','require_pod'=>false,'events'=>[],'logic'=>[],'actions'=>[],'entities'=>[],'options'=>[],'status'=>'DEMO '.$code,'details'=>'DEMO transport '.$code];
$tripConfig=row('order_configs',['company_uuid'=>$company,'flow'=>json_encode($tripFlow)]);
$tripPickup=row('places',['company_uuid'=>$company,'location'=>$point]);$tripDropoff=row('places',['company_uuid'=>$company,'location'=>$point]);
$tripPayload=row('payloads',['company_uuid'=>$company,'pickup_uuid'=>$tripPickup,'dropoff_uuid'=>$tripDropoff]);
$tripTracking=row('tracking_numbers',['company_uuid'=>$company,'type'=>'order']);
$trip=row('orders',['company_uuid'=>$company,'driver_assigned_uuid'=>$driver,'vehicle_assigned_uuid'=>$vehicle,'payload_uuid'=>$tripPayload,'order_config_uuid'=>$tripConfig,'tracking_number_uuid'=>$tripTracking,'status'=>'dispatched','dispatched'=>1]);
$tripId=DB::table('orders')->where('uuid',$trip)->value('public_id');
DB::table('tracking_numbers')->where('uuid',$tripTracking)->update(['owner_uuid'=>$trip,'owner_type'=>(new Fleetbase\FleetOps\Models\Order)->getMorphClass()]);
$viewTrip=fn()=>collect($service->snapshot($service->context(req([],$token)))['orders'])->firstWhere('id',$tripId);
$tripRequest=fn($code,$extra=[])=>req(['action_id'=>(string)Str::uuid(),'expected_revision'=>$viewTrip()['revision'],'activity_code'=>$code,'confirmed'=>true,...$extra],$token);
check($viewTrip()['next_activities']===[],'trip requires explicit acceptance');
denied(fn()=>$service->mutate($tripRequest('started'),'activity',$tripId),409);
$service->mutate(req(['action_id'=>(string)Str::uuid(),'expected_revision'=>$viewTrip()['revision']],$token),'ack',$tripId);
check($viewTrip()['next_activities'][0]['code']==='started','only configured next trip step advertised');
denied(fn()=>$service->mutate($tripRequest('completed',['handover_confirmed'=>true]),'activity',$tripId),409);
denied(fn()=>$service->mutate($tripRequest('started',['confirmed'=>false]),'activity',$tripId),422);
// Earlier test fix intentionally had unknown mock state; it is not completion evidence.
denied(fn()=>$service->mutate($tripRequest('started'),'activity',$tripId),409);
$tripGps=[...$gps,'action_id'=>(string)Str::uuid(),'recorded_at'=>(int)round(microtime(true)*1000),'mock_location'=>false];
$service->mutate(req($tripGps,$token),'gps');
$oldTripFlow=$tripFlow;$tripFlow['started']['events']=['order.started'];
DB::table('order_configs')->where('uuid',$tripConfig)->update(['flow'=>json_encode($tripFlow)]);
check($viewTrip()['next_activities']===[],'custom event workflow excluded');denied(fn()=>$service->mutate($tripRequest('started'),'activity',$tripId),409);
DB::table('order_configs')->where('uuid',$tripConfig)->update(['flow'=>json_encode($oldTripFlow)]);
DB::table('orders')->where('uuid',$trip)->update(['pod_required'=>1]);
check($viewTrip()['next_activities']===[],'proof required workflow excluded');denied(fn()=>$service->mutate($tripRequest('started'),'activity',$tripId),409);
DB::table('orders')->where('uuid',$trip)->update(['pod_required'=>0]);
// After an order edit crew must review/accept the new revision.
$service->mutate(req(['action_id'=>(string)Str::uuid(),'expected_revision'=>$viewTrip()['revision']],$token),'ack',$tripId);
$staleTrip=$tripRequest('started');
DB::table('order_configs')->where('uuid',$tripConfig)->update(['flow'=>json_encode([...$oldTripFlow,'started'=>[...$oldTripFlow['started'],'details'=>'DEMO changed details']])]);
denied(fn()=>$service->mutate($staleTrip,'activity',$tripId),409);
$tripGps['action_id']=(string)Str::uuid();$tripGps['recorded_at']=(int)round(microtime(true)*1000)+1;
$gpsResult=$service->mutate(req($tripGps,$token),'gps');
check(!isset($gpsResult['_session_hash'])&&!isset($service->mutate(req($tripGps,$token),'gps')['_session_hash']),'private session binding never returned or replayed');
$gpsReceipt=DB::table('mapa_mobile_receipts')->where('action_id',$tripGps['action_id'])->first();
$gpsStored=json_decode($gpsReceipt->result,true);$wrongSession=$gpsStored;$wrongSession['_session_hash']=str_repeat('0',64);
DB::table('mapa_mobile_receipts')->where('id',$gpsReceipt->id)->update(['result'=>json_encode($wrongSession)]);
denied(fn()=>$service->mutate($tripRequest('started'),'activity',$tripId),409);
DB::table('mapa_mobile_receipts')->where('id',$gpsReceipt->id)->update(['result'=>$gpsReceipt->result]);
DB::table('tracking_numbers')->where('uuid',$tripTracking)->update(['owner_uuid'=>$order]);
check($viewTrip()['next_activities']===[],'another order tracking number cannot be reused');
denied(fn()=>$service->mutate($tripRequest('started'),'activity',$tripId),409);
DB::table('tracking_numbers')->where('uuid',$tripTracking)->update(['owner_uuid'=>$trip]);
if(isset($mapaDedicatedQaApp))require __DIR__.'/trip-source-coordination-fixture.php';
$startTrip=$tripRequest('started');$started=$service->mutate($startTrip,'activity',$tripId);
check($started['status']==='started'&&!$started['completed'],'native trip started');
check(DB::table('orders')->where('uuid',$trip)->value('started')==1&&DB::table('orders')->where('uuid',$trip)->value('started_at')!==null,'native start flags and time');
check(DB::table('drivers')->where('uuid',$driver)->value('current_job_uuid')===$trip,'current trip linked');
check($service->mutate($startTrip,'activity',$tripId)['replayed'],'trip retry uses immutable receipt');
check(DB::table('tracking_statuses')->where('tracking_number_uuid',$tripTracking)->count()===1,'replay cannot duplicate tracking');
check($viewTrip()['acknowledged']&&$viewTrip()['next_activities'][0]['code']==='enroute','own transition preserves acknowledgement and next edge');
DB::table('drivers')->where('uuid',$driver)->update(['current_job_uuid'=>null]);
denied(fn()=>$service->mutate($tripRequest('enroute'),'activity',$tripId),409);
DB::table('drivers')->where('uuid',$driver)->update(['current_job_uuid'=>$trip]);
$service->mutate($tripRequest('enroute'),'activity',$tripId);
denied(fn()=>$service->mutate($tripRequest('completed'),'activity',$tripId),422);
$finishTrip=$tripRequest('completed',['handover_confirmed'=>true]);$completed=$service->mutate($finishTrip,'activity',$tripId);
check($completed['completed']&&DB::table('orders')->where('uuid',$trip)->value('status')==='completed','confirmed native hospital handover completed');
check($viewTrip()===null,'completed call removed from active snapshot');
check(DB::table('drivers')->where('uuid',$driver)->value('current_job_uuid')===null,'only completed current trip released');
check($service->mutate($finishTrip,'activity',$tripId)['replayed'],'completion receipt recovered after terminal state');
check(DB::table('tracking_statuses')->where('tracking_number_uuid',$tripTracking)->count()===3,'exactly one tracking record per configured step');
$tripStatus=DB::table('tracking_statuses')->where('tracking_number_uuid',$tripTracking)->where('code','COMPLETED')->first();
$tripAudit=json_decode($tripStatus->meta,true)['mapa_mobile'];
check($tripStatus->company_uuid===$company&&$tripStatus->complete==1&&$tripAudit['handover_confirmed']===true&&$tripAudit['proof_of_travel']===false,'scoped tracking and honest confirmation audit');
check(DB::table('tracking_numbers')->where('uuid',$tripTracking)->value('status_uuid')===$tripStatus->uuid,'native tracking pointer advances atomically');
check(DB::table('orders')->where('uuid',$trip)->value('driver_assigned_uuid')===$driver,'completed trip retains assigned crew history');
if(isset($tripCoordJourney)){
    $queued=DB::table('mapa_source_dispatch_outbox')->where('journey_id',$tripCoordJourney)->orderBy('sequence')->get();
    check($queued->count()===4,'actual native trip queues exactly four source phases despite native retries');
    check($queued->map(fn($row)=>json_decode($row->command,true)['next_status'])->all()===['en_route','arrived_scene','transporting','completed'],'actual native activity preserves source ownership phase order');
    check($queued->every(fn($row)=>$row->state==='pending')&&DB::table('mapa_source_journeys')->where('journey_id',$tripCoordJourney)->value('terminal_at')===null,'native completion alone does not release unacknowledged source ownership');
    check(json_decode($queued->last()->command,true)['actor_id']===$user&&$queued->last()->native_action_id===$finishTrip->json('action_id'),'outbox completion retains authenticated crew and exact native handover action');
    DB::table('mapa_source_dispatch_outbox')->where('journey_id',$tripCoordJourney)->delete();DB::table('mapa_source_journeys')->where('journey_id',$tripCoordJourney)->delete();
    DB::table('mapa_source_connections')->where('company_uuid',$company)->where('source_id','1')->whereIn('dataset',['drivers','ambulances'])->delete();
    if($tripCoordPrevious===null)unlink($tripCoordFile);else file_put_contents($tripCoordFile,$tripCoordPrevious);
    config(['mapa_mobile.source_dispatch_coordination_enabled'=>$tripCoordPrior[0],'mapa_mobile.source_sync_enabled'=>$tripCoordPrior[1]]);
}
DB::table('orders')->where('uuid',$trip)->update(['driver_assigned_uuid'=>$otherDriver]);denied(fn()=>$service->mutate($finishTrip,'activity',$tripId),404);
DB::table('orders')->where('uuid',$trip)->delete();
DB::table('tracking_statuses')->where('tracking_number_uuid',$tripTracking)->delete();
DB::table('mapa_mobile_receipts')->where('user_uuid',$user)->where('action_id','<>',$gps['action_id'])->whereNotNull('result->gps_evidence')->delete();
config(['mapa_mobile.trips_enabled'=>false]);
